/* RL-80 sound builder.
   Runs in a background worker so the page never freezes while sounds are made.
   Every built-in sound is rebuilt here from measurements of a real drum machine:
   ringing tones, pitch sweeps and noise loudness over time. No audio recordings are stored. */
/* 909-style cymbals: build a metallic hit once, crush it to 6 bits (like the 909's sample chips),
   then play it back through a decay envelope, as the 909 does. */
function biquad(x,type,f,Q,sr){
  const w=2*Math.PI*f/sr,c=Math.cos(w),al=Math.sin(w)/(2*Q);let b0,b1,b2;
  if(type==='hp'){b0=(1+c)/2;b1=-(1+c);b2=b0}else if(type==='lp'){b0=(1-c)/2;b1=1-c;b2=b0}else{b0=al;b1=0;b2=-al}
  const a0=1+al,a1=-2*c/a0,a2=(1-al)/a0;b0/=a0;b1/=a0;b2/=a0;
  let x1=0,x2=0,y1=0,y2=0;
  for(let i=0;i<x.length;i++){const xi=x[i],y=b0*xi+b1*x1+b2*x2-a1*y1-a2*y2;x2=x1;x1=xi;y2=y1;y1=y;x[i]=y}
  return x;
}
