    for(let tries=0;tries<6;tries++){const y=make(m.ratios.map(()=>r()*6.283));let pk=0,ss=0;const w=Math.min(n,2205);for(let i=0;i<w;i++){pk=Math.max(pk,Math.abs(y[i]));ss+=y[i]*y[i]}const c=pk/Math.sqrt(ss/w);if(c<bc){bc=c;best=y}}
