  for(const [f,d,a,b] of Rm.comp){const rr=Math.exp(-d/SR),th=2*Math.PI*f/SR,c=Math.cos(th),s=Math.sin(th);let zr=1,zi=0;
    for(let k=0;k<n;k++){y[k]+=a*zr-b*zi;const nr=(zr*c-zi*s)*rr;zi=(zr*s+zi*c)*rr;zr=nr}}
